<!-- SECTION 6: DECADE-BY-DECADE PERFORMANCE COMPARISON -->
<!-- ============================================================ -->
<section id="decade-comparison">
  <h2>Decade-by-Decade Performance Comparison</h2>
  <div class="section-obj">Comparison of AXP's performance across each decade in terms of returns, volatility, and dividend activity, contextualized within broader economic environments.</div>

  <div class="chart-box">
    <canvas id="chartDecadeReturns"></canvas>
  </div>

  <div class="chart-row">
    <div class="chart-box">
      <canvas id="chartDecadeVol"></canvas>
    </div>
    <div class="chart-box">
      <canvas id="chartDecadeCagr"></canvas>
    </div>
  </div>

