#!/usr/bin/env python3
"""Generate the final HTML report for AXP stock analysis."""

import json

def load_analysis():
    with open('/app/output/analysis.json', 'r') as f:
        return json.load(f)

def build_html(a):
    """Build the complete HTML report."""
    kpi = a['kpis']
    meta = a['meta']

    # Format large numbers
    def fmt_dollar(v):
        if abs(v) >= 1000:
            return f"${v:,.0f}"
        return f"${v:,.2f}"

    def fmt_pct(v):
        return f"{v:,.1f}%"

    def fmt_num(v):
        if v >= 1_000_000_000:
            return f"{v/1_000_000_000:.1f}B"
        if v >= 1_000_000:
            return f"{v/1_000_000:.1f}M"
        if v >= 1_000:
            return f"{v/1_000:.0f}K"
        return str(v)

    # Build KPI cards HTML
    kpi_cards = f"""
    <div class="kpi-grid">
        <div class="kpi-card">
            <div class="kpi-label">Cumulative Total Return</div>
            <div class="kpi-value positive">{fmt_pct(kpi['cumulative_return_pct'])}</div>
            <div class="kpi-sub">${kpi['start_price']:.2f} → ${kpi['end_price']:.2f}</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">CAGR</div>
            <div class="kpi-value positive">{kpi['cagr_pct']}%</div>
            <div class="kpi-sub">Over {meta['total_years']} years</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Maximum Drawdown</div>
            <div class="kpi-value negative">-{fmt_pct(kpi['max_drawdown_pct'])}</div>
            <div class="kpi-sub">{kpi['max_drawdown_start']} → {kpi['max_drawdown_end']}</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Annualized Volatility</div>
            <div class="kpi-value neutral">{kpi['annualized_volatility_pct']}%</div>
            <div class="kpi-sub">Daily σ × √252</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Total Dividends Per Share</div>
            <div class="kpi-value positive">{fmt_dollar(kpi['total_dividends_per_share'])}</div>
            <div class="kpi-sub">Cumulative since 1972</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">All-Time High</div>
            <div class="kpi-value highlight">{fmt_dollar(meta['at_all_time_high'])}</div>
            <div class="kpi-sub">On {meta['ath_date']}</div>
        </div>
    </div>
    """

    # Sub-period table rows
    sub_period_rows = ''
    for sp in a['sub_periods']:
        cls = 'positive' if sp['return_pct'] >= 0 else 'negative'
        sub_period_rows += f"""<tr>
            <td>{sp['name']}</td>
            <td>{sp['start_date']}</td>
            <td>{sp['end_date']}</td>
            <td>{sp['years']} yrs</td>
            <td>${sp['start_price']:.2f}</td>
            <td>${sp['end_price']:.2f}</td>
            <td class="{cls}">{sp['return_pct']:+.1f}%</td>
            <td class="{cls}">{sp['cagr_pct']:+.1f}%</td>
        </tr>"""

    # Decade table rows
    decade_rows = ''
    for dec in sorted(a['decades'].keys()):
        d = a['decades'][dec]
        cls_ret = 'positive' if d['total_return_pct'] >= 0 else 'negative'
        cls_cagr = 'positive' if d['cagr_pct'] >= 0 else 'negative'
        decade_rows += f"""<tr>
            <td>{dec}s</td>
            <td>{d['start_price']:.2f}</td>
            <td>{d['end_price']:.2f}</td>
            <td class="{cls_ret}">{d['total_return_pct']:+.1f}%</td>
            <td class="{cls_cagr}">{d['cagr_pct']:+.1f}%</td>
            <td class="negative">-{d['max_drawdown_pct']:.1f}%</td>
            <td>{d['annualized_volatility_pct']:.1f}%</td>
            <td>${d['total_dividends']:.2f}</td>
            <td>{fmt_num(d['total_volume'])}</td>
        </tr>"""

    # Annual returns table (last 20 years shown prominently, rest collapsed)
    annual_rows = ''
    for ar in a['annual_returns']:
        cls = 'positive' if ar['return_pct'] >= 0 else 'negative'
        if ar['year'] >= 2006:
            annual_rows += f'<tr><td>{ar["year"]}</td><td class="{cls}">{ar["return_pct"]:+.1f}%</td></tr>\n'
    # Build hidden rows for older years
    annual_rows_older = ''
    for ar in a['annual_returns']:
        if ar['year'] < 2006:
            annual_rows_older += f'<tr class="old-year"><td>{ar["year"]}</td><td class="{"positive" if ar["return_pct"] >= 0 else "negative"}">{ar["return_pct"]:+.1f}%</td></tr>\n'

    # Major phases (top 5 worst drawdowns and top 5 best rallies)
    bear_phases = sorted([p for p in a['phases'] if p['type'] == 'bear'], key=lambda x: x['decline_pct'], reverse=True)[:8]
    bull_phases = sorted([p for p in a['phases'] if p['type'] == 'bull'], key=lambda x: x['gain_pct'], reverse=True)[:8]

    bear_rows = ''
    for p in bear_phases:
        bear_rows += f"""<tr>
            <td>{p['start_date']} → {p['end_date']}</td>
            <td>${p['start_price']:.2f}</td>
            <td>${p['end_price']:.2f}</td>
            <td class="negative">-{p['decline_pct']:.1f}%</td>
        </tr>"""

    bull_rows = ''
    for p in bull_phases:
        bull_rows += f"""<tr>
            <td>{p['start_date']} → {p['end_date']}</td>
            <td>${p['start_price']:.2f}</td>
            <td>${p['end_price']:.2f}</td>
            <td class="positive">+{p['gain_pct']:.1f}%</td>
        </tr>"""

    # Dividend yield history (recent years)
    div_yield_rows = ''
    for dy in a['dividend_yield_history']:
        if dy['year'] >= 2000:
            div_yield_rows += f"""<tr>
                <td>{dy['year']}</td>
                <td>${dy['dividend']:.4f}</td>
                <td>${dy['avg_price']:.2f}</td>
                <td>{dy['yield_pct']:.2f}%</td>
            </tr>"""

    # Build the full HTML
    # Get key at-dates for annotations
    # Find COVID crash
    covid_data = [(d['date'], d['close']) for d in a['monthly_closes'] if d['date'].startswith('2020')]
    covid_low = min(covid_data, key=lambda x: x[1]) if covid_data else ('2020-03', 0)

    # Find financial crisis data
    gfc_data = [(d['date'], d['close']) for d in a['monthly_closes'] if '2008' <= d['date'] < '2010']
    gfc_low = min(gfc_data, key=lambda x: x[1]) if gfc_data else ('2009-03', 0)

    # Dot-com
    dotcom_data = [(d['date'], d['close']) for d in a['monthly_closes'] if '1999' <= d['date'] < '2003']
    dotcom_high = max(dotcom_data, key=lambda x: x[1]) if dotcom_data else ('2000', 0)
    dotcom_low = min(dotcom_data, key=lambda x: x[1]) if dotcom_data else ('2002', 0)

    # Black Monday
    bm_data = [(d['date'], d['close']) for d in a['monthly_closes'] if d['date'].startswith('1987')]

    # Build JSON data for charts
    monthly_json = json.dumps([{'x': d['date'], 'y': d['close']} for d in a['monthly_closes']])
    dd_json = json.dumps([{'x': d['date'], 'y': d['drawdown']} for d in a['sampled_drawdowns']])
    ann_ret_json = json.dumps([{'x': ar['year'], 'y': ar['return_pct']} for ar in a['annual_returns']])
    vol_json = json.dumps([{'x': a['rolling_volatility']['dates'][i], 'y': a['rolling_volatility']['values'][i]} for i in range(0, len(a['rolling_volatility']['dates']), max(1, len(a['rolling_volatility']['dates']) // 500))])
    div_events_json = json.dumps([{'x': e['date'], 'y': e['amount']} for e in a['dividend_events']])
    div_yield_json = json.dumps([{'x': dy['year'], 'y': dy['yield_pct']} for dy in a['dividend_yield_history']])

    # Volume data for chart
    vol_chart_json = json.dumps([{'x': d['date'], 'y': d['volume']} for d in a['sampled_volume']])

    # Sub-period chart data
    sub_chart_labels = json.dumps([sp['name'].split(' (')[0] for sp in a['sub_periods']])
    sub_chart_cagr = json.dumps([sp['cagr_pct'] for sp in a['sub_periods']])
    sub_chart_ret = json.dumps([sp['return_pct'] for sp in a['sub_periods']])

    # Decade chart data
    decade_labels = json.dumps([f"{dec}s" for dec in sorted(a['decades'].keys())])
    decade_returns = json.dumps([a['decades'][dec]['total_return_pct'] for dec in sorted(a['decades'].keys())])
    decade_vol = json.dumps([a['decades'][dec]['annualized_volatility_pct'] for dec in sorted(a['decades'].keys())])
    decade_cagr = json.dumps([a['decades'][dec]['cagr_pct'] for dec in sorted(a['decades'].keys())])

    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>American Express (AXP) Historical Stock Performance Report: 1972–2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-adapter-date-fns@3.0.0/dist/chartjs-adapter-date-fns.bundle.min.js"></script>
<style>
  :root {{
    --blue: #002663;
    --blue-light: #006FCF;
    --gold: #B59A67;
    --gray-900: #1a1a2e;
    --gray-700: #4a4a5a;
    --gray-500: #8a8a9a;
    --gray-200: #e8e8ed;
    --gray-100: #f5f5f8;
    --green: #0d7b4d;
    --red: #c0392b;
    --white: #ffffff;
  }}

  * {{ box-sizing: border-box; margin: 0; padding: 0; }}

  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
    color: var(--gray-900);
    background: #f0f2f5;
    line-height: 1.6;
  }}

  .report-cover {{
    background: linear-gradient(135deg, var(--blue) 0%, #001a3d 100%);
    color: white;
    padding: 80px 60px;
    text-align: center;
  }}

  .report-cover h1 {{
    font-size: 2.8em;
    font-weight: 700;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
  }}

  .report-cover .subtitle {{
    font-size: 1.2em;
    opacity: 0.85;
    font-weight: 400;
    margin-bottom: 6px;
  }}

  .report-cover .meta-line {{
    font-size: 0.9em;
    opacity: 0.6;
    margin-top: 20px;
  }}

  .report-header-bar {{
    background: var(--blue);
    color: white;
    padding: 12px 60px;
