  }}

  tbody tr:hover {{ background: var(--gray-100); }}

  td.positive {{ color: var(--green); font-weight: 600; }}
  td.negative {{ color: var(--red); font-weight: 600; }}

  /* Charts */
  .chart-box {{
    background: white;
    border-radius: 10px;
    padding: 30px;
    margin: 25px 0;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
