<body>

<header class="report-header-bar">
  <span class="ticker">AXP</span>
  <span>NYSE &bull; Financial Services &bull; Report Generated {meta['generated'][:10]}</span>
</header>

<div class="report-cover">
  <div class="subtitle">INVESTOR-GRADE FINANCIAL REPORT</div>
  <h1>American Express (AXP)<br>Historical Stock Performance</h1>
  <div class="subtitle">Comprehensive Analysis Spanning Over 50 Years of Daily Trading Data</div>
