#!/usr/bin/env python3
"""Generate the final HTML report for AXP stock analysis."""

import json

def load_analysis():
    with open('/app/output/analysis.json', 'r') as f:
        return json.load(f)

def build_html(a):
    """Build the complete HTML report."""
    kpi = a['kpis']
    meta = a['meta']

    # Format large numbers
    def fmt_dollar(v):
        if abs(v) >= 1000:
            return f"${v:,.0f}"
        return f"${v:,.2f}"

    def fmt_pct(v):
        return f"{v:,.1f}%"

    def fmt_num(v):
        if v >= 1_000_000_000:
            return f"{v/1_000_000_000:.1f}B"
        if v >= 1_000_000:
            return f"{v/1_000_000:.1f}M"
        if v >= 1_000:
            return f"{v/1_000:.0f}K"
        return str(v)

    # Build KPI cards HTML
    kpi_cards = f"""
    <div class="kpi-grid">
        <div class="kpi-card">
            <div class="kpi-label">Cumulative Total Return</div>
            <div class="kpi-value positive">{fmt_pct(kpi['cumulative_return_pct'])}</div>
            <div class="kpi-sub">${kpi['start_price']:.2f} → ${kpi['end_price']:.2f}</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">CAGR</div>
            <div class="kpi-value positive">{kpi['cagr_pct']}%</div>
            <div class="kpi-sub">Over {meta['total_years']} years</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Maximum Drawdown</div>
            <div class="kpi-value negative">-{fmt_pct(kpi['max_drawdown_pct'])}</div>
            <div class="kpi-sub">{kpi['max_drawdown_start']} → {kpi['max_drawdown_end']}</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Annualized Volatility</div>
            <div class="kpi-value neutral">{kpi['annualized_volatility_pct']}%</div>
            <div class="kpi-sub">Daily σ × √252</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">Total Dividends Per Share</div>
            <div class="kpi-value positive">{fmt_dollar(kpi['total_dividends_per_share'])}</div>
            <div class="kpi-sub">Cumulative since 1972</div>
        </div>
        <div class="kpi-card">
            <div class="kpi-label">All-Time High</div>
            <div class="kpi-value highlight">{fmt_dollar(meta['at_all_time_high'])}</div>
            <div class="kpi-sub">On {meta['ath_date']}</div>
        </div>
    </div>
    """

    # Sub-period table rows
    sub_period_rows = ''
    for sp in a['sub_periods']:
        cls = 'positive' if sp['return_pct'] >= 0 else 'negative'
        sub_period_rows += f"""<tr>
            <td>{sp['name']}</td>
            <td>{sp['start_date']}</td>
            <td>{sp['end_date']}</td>
            <td>{sp['years']} yrs</td>
            <td>${sp['start_price']:.2f}</td>
            <td>${sp['end_price']:.2f}</td>
            <td class="{cls}">{sp['return_pct']:+.1f}%</td>
            <td class="{cls}">{sp['cagr_pct']:+.1f}%</td>
        </tr>"""

    # Decade table rows
    decade_rows = ''
    for dec in sorted(a['decades'].keys()):
        d = a['decades'][dec]
        cls_ret = 'positive' if d['total_return_pct'] >= 0 else 'negative'
        cls_cagr = 'positive' if d['cagr_pct'] >= 0 else 'negative'
        decade_rows += f"""<tr>
            <td>{dec}s</td>
            <td>{d['start_price']:.2f}</td>
            <td>{d['end_price']:.2f}</td>
            <td class="{cls_ret}">{d['total_return_pct']:+.1f}%</td>
            <td class="{cls_cagr}">{d['cagr_pct']:+.1f}%</td>
            <td class="negative">-{d['max_drawdown_pct']:.1f}%</td>
            <td>{d['annualized_volatility_pct']:.1f}%</td>
            <td>${d['total_dividends']:.2f}</td>
            <td>{fmt_num(d['total_volume'])}</td>
        </tr>"""

    # Annual returns table (last 20 years shown prominently, rest collapsed)
    annual_rows = ''
    for ar in a['annual_returns']:
        cls = 'positive' if ar['return_pct'] >= 0 else 'negative'
        if ar['year'] >= 2006:
            annual_rows += f'<tr><td>{ar["year"]}</td><td class="{cls}">{ar["return_pct"]:+.1f}%</td></tr>\n'
    # Build hidden rows for older years
    annual_rows_older = ''
    for ar in a['annual_returns']:
        if ar['year'] < 2006:
            annual_rows_older += f'<tr class="old-year"><td>{ar["year"]}</td><td class="{"positive" if ar["return_pct"] >= 0 else "negative"}">{ar["return_pct"]:+.1f}%</td></tr>\n'

    # Major phases (top 5 worst drawdowns and top 5 best rallies)
    bear_phases = sorted([p for p in a['phases'] if p['type'] == 'bear'], key=lambda x: x['decline_pct'], reverse=True)[:8]
    bull_phases = sorted([p for p in a['phases'] if p['type'] == 'bull'], key=lambda x: x['gain_pct'], reverse=True)[:8]

    bear_rows = ''
    for p in bear_phases:
